import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./Emergency.css";

const Emergency = () => {
  const navigate = useNavigate();

  const [contacts, setContacts] = useState([]);
  const [location, setLocation] = useState("");
  const [highRisk, setHighRisk] = useState(false);

  /* =========================
     FETCH CONTACTS
  ========================= */
  useEffect(() => {
    axios
      .get("http://localhost:5000/api/contacts")
      .then((res) => setContacts(res.data))
      .catch((err) => console.error(err));
  }, []);

  /* =========================
     CHECK LOCATION
  ========================= */
  useEffect(() => {
    if (!navigator.geolocation) return;

    navigator.geolocation.getCurrentPosition((pos) => {
      const { latitude, longitude } = pos.coords;

      if (latitude >= 8 && latitude <= 37 && longitude >= 68 && longitude <= 97) {
        setLocation("India 🇮🇳");
      } else {
        setLocation("Outside India 🌍");
      }
    });
  }, []);

  /* =========================
     CHECK HIGH RISK STATUS
  ========================= */
  const checkHighRisk = async () => {
    try {
      const res = await axios.get(
        "http://localhost:5000/api/calls/recent"
      );

      if (res.data.length >= 3) {
        setHighRisk(true);
      }
    } catch (err) {
      console.error(err);
    }
  };

  /* =========================
     HANDLE CALL
  ========================= */
  const handleCall = async (contact) => {
    try {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        await axios.post("http://localhost:5000/api/calls", {
          contactName: contact.name,
          phoneNumber: contact.number,
          latitude: pos.coords.latitude,
          longitude: pos.coords.longitude,
        });

        await checkHighRisk();

        window.location.href = `tel:${contact.number}`;
      });
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="emergency-container">
      <h1>🚨 Emergency Contacts</h1>

      {/* STATUS CARD */}
      <div className="risk-card">
        <p>📍 Location: <b>{location || "Detecting..."}</b></p>
        <p>🕒 Time: <b>{new Date().toLocaleTimeString()}</b></p>

        {highRisk && (
          <div className="high-risk-alert">
            🚨 HIGH RISK DETECTED <br />
            Multiple emergency calls in short time!
          </div>
        )}
      </div>

      <div className="contact-grid">
        {contacts.map((contact) => (
          <div key={contact._id} className="contact-card">
            <h3>{contact.name}</h3>
            <p>{contact.number}</p>
            <button
              className="call-btn"
              onClick={() => handleCall(contact)}
            >
              📞 Call Now
            </button>
          </div>
        ))}
      </div>

      <button className="back-btn" onClick={() => navigate("/")}>
        ⬅ Back to Home
      </button>
    </div>
  );
};

export default Emergency;
